select le1_0.id from labels le1_0 order by 1
select o1_1.id,o1_1.status,o1_1.total,le1_0.id from labels le1_0 join order_labels o1_0 on le1_0.id=o1_0.label_id join orders o1_1 on o1_1.id=o1_0.order_id left join order_items i1_0 on o1_1.id=i1_0.order_id where (o1_1.status=? or i1_0.product_code=?) and exists(select 1 from order_items i2_0 where i2_0.product_code like ? escape '\' and o1_1.id=i2_0.order_id) and o1_1.id<? and le1_0.id in (?,?,?,?,?,?,?,?,?,?) order by 1
